def solve(g):
    from collections import Counter
    H, W = len(g), len(g[0])
    sep_rows = {r for r in range(H) if len(set(g[r])) == 1}
    sep_cols = {c for c in range(W) if len(set(g[r][c] for r in range(H))) == 1}

    def bands(allr):
        res, cur = [], []
        for x in allr:
            if cur and x == cur[-1] + 1:
                cur.append(x)
            else:
                if cur: res.append(cur)
                cur = [x]
        if cur: res.append(cur)
        return res

    rb = bands([r for r in range(H) if r not in sep_rows])
    cb = bands([c for c in range(W) if c not in sep_cols])

    best, best_idx = [], (0, 0)
    for i, r_band in enumerate(rb):
        for j, c_band in enumerate(cb):
            band_cells = [g[r][c] for r in r_band for c in c_band]
            mode = Counter(band_cells).most_common(1)[0][0]
            pattern = [g[r][c] for r in r_band for c in c_band if g[r][c] != mode]
            if len(pattern) > len(best):
                best = pattern
                best_idx = (i, j)

    out = [row[:] for row in g]
